        db $00, $38, $44, $38, $44, $44, $38, $00
        db $00, $38, $44, $3C, $04, $08, $30, $00
        db $00, $00, $00, $10, $00, $00, $10, $00
        db $00, $00, $00, $10, $00, $00, $10, $20
        db $00, $00, $08, $10, $20, $10, $08, $00
        db $00, $00, $00, $7C, $00, $7C, $00, $00
        db $00, $00, $20, $10, $08, $10, $20, $00
        db $00, $38, $44, $08, $10, $00, $10, $00
        db $00, $38, $44, $5C, $54, $58, $40, $38
